import type * as Leaflet from 'leaflet';
import type * as Three from 'three';
import type { JourneyTools } from './journey-tools.js';
import type { XrAnchors } from './xr-anchors.js';
import type { XrControls } from './xr-controls.js';

export type ThreeModule = typeof Three;
export type TranslationValues = Record<string, string | number | boolean | null | undefined>;
export type Translate = (key: string, values?: TranslationValues) => string;
export type Language = 'en' | 'fr';
export interface Coordinates { latitude: number; longitude: number }
export interface Target extends Coordinates {
  id: string;
  radiusMeters: number;
  metrics?: { key: string; distance: number; bearing: number };
}
export interface RouteDocument {
  points: Target[];
  journey: { name: string; sequence: string[] };
}
export interface Journey {
  name: string;
  sequence: string[];
  activeStepIndex: number;
  totalPlannedDistanceMeters: number;
  legRemainders: number[];
  awaitingExit: boolean;
  paused: boolean;
}
export interface PositionReading {
  latitude: number | null;
  longitude: number | null;
  locationSource: string;
  lastPositionTs: number;
  accuracyMeters: number | null;
}
export interface CompassReading {
  headingDeg: number;
  hasHeading: boolean;
  lastHeadingTs: number;
  headingSource: string;
}
export interface UserState extends PositionReading, CompassReading {
  locationSource: 'none' | 'manual' | 'geolocation';
  headingSource: 'none' | 'compass';
}
export interface CompassEvent {
  alpha?: number | null;
  absolute?: boolean;
  webkitCompassHeading?: number;
  webkitCompassAccuracy?: number;
}
export interface QuaternionReading { x: number; y: number; z: number; w: number }
export interface FeedbackPreferences { sound: boolean; haptics: boolean }
export type LogLevel = 'info' | 'warn' | 'error';
export interface XrButton { id: string; label: string; disabled?: boolean }
export interface MapTile {
  image: HTMLImageElement;
  status: 'loading' | 'ready' | 'error';
  failedAt?: number;
}
export interface AppUi {
  cameraView: HTMLVideoElement;
  overlayArrows: HTMLElement;
  mapFollowButton: HTMLButtonElement;
  mapEdgeTargets: HTMLElement;
  languageLabel: HTMLElement;
  languageSelect: HTMLSelectElement;
  versionLine: HTMLElement;
  statusLine: HTMLElement;
  distanceSummary: HTMLElement;
  journeySummary: HTMLElement;
  xrSummary: HTMLElement;
  startButton: HTMLButtonElement;
  enterArButton: HTMLButtonElement;
  aboutLink: HTMLAnchorElement;
  aboutModal: HTMLElement;
  aboutCloseButton: HTMLButtonElement;
  aboutTitle: HTMLElement;
  aboutCodedWithLabel: HTMLElement;
  aboutLicenseLabel: HTMLElement;
  aboutMapDataLabel: HTMLElement;
  aboutMapLibraryLabel: HTMLElement;
  aboutXrLibraryLabel: HTMLElement;
  aboutFaviconLabel: HTMLElement;
}
export interface AppState {
  user: UserState;
  targets: Target[];
  targetsById: Map<string, Target>;
  journey: Journey;
  map: Leaflet.Map | null;
  tools: JourneyTools;
  ui: AppUi;
  layers: {
    userMarker: Leaflet.CircleMarker | null;
    headingMarker: Leaflet.Marker | null;
    targetCircles: Leaflet.Circle[];
    targetMarkers: Leaflet.CircleMarker[];
    routeLine?: Leaflet.Polyline;
  };
  watchers: { geolocation: number | null };
  capabilities: { orientationForArrows: boolean };
  app: {
    experienceReady: boolean; starting: boolean;
    statusKey: string; statusValues: TranslationValues;
    cameraPending: Promise<void> | null; cameraGeneration: number; geoPending: Promise<void> | null;
    orientationListening: boolean; renderFrame: number | null; freshnessTimer: number | null;
    lastMapPositionTs: number; arrowNodes: Map<string, HTMLDivElement>; edgeNodes: Map<string, HTMLDivElement>; edgeFrame: number | null;
    geoErrorKey: string | null; cameraError: string | null;
  };
  mapControl: { followUser: boolean; hasCenteredOnce: boolean };
  xr: {
    supported: boolean; session: XRSession | null;
    renderer: Three.WebGLRenderer | null; scene: Three.Scene | null; camera: Three.PerspectiveCamera | null;
    arrowMeshes: Map<string, Three.Group>;
    starting: boolean; northOffsetDeg: number | null; northSource: 'manual' | 'compass' | null;
    viewerYawDeg: number; viewerPose: XRViewerPose | null;
    resumeCamera: boolean; mapRevision: number; mapSignature: string; hudSignature: string;
    waitingMesh: Three.Group | null; domOverlayActive: boolean;
    mapCanvas: HTMLCanvasElement | null; mapContext: CanvasRenderingContext2D | null;
    mapTexture: Three.CanvasTexture | null; mapPlane: Three.Mesh | null;
    mapTileCache: Map<string, MapTile>; mapLastDrawMs: number;
    hudCanvas: HTMLCanvasElement | null; hudContext: CanvasRenderingContext2D | null;
    hudTexture: Three.CanvasTexture | null; hudPlane: Three.Mesh | null; hudLastDrawMs: number;
    closestArrowMesh: Three.Group | null; anchors: XrAnchors | null;
    reference: XRReferenceSpace | null; tracking: string | null; watchdog: number | null;
    controls: XrControls | null;
  };
  i18n: { messages: Record<Language, Record<string, string>> | null; language: Language };
}
